module lucky_permutation_triple (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    output reg done,\n    output reg valid,\n    output reg [7:0] a [0:7],\n    output reg [7:0] b [0:7],\n    output reg [7:0] c [0:7]\n);\n\n    reg state;\n    localparam IDLE = 1'b0;\n    localparam DONE_ST = 1'b1;\n\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            valid <= 1'b0;\n            for (i = 0; i < 8; i = i + 1) begin\n                a[i] <= 8'd0;\n                b[i] <= 8'd0;\n                c[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        valid <= (n >= 4'd1) && (n <= 4'd8) && (n[0] == 1'b1);\n\n                        for (i = 0; i < 8; i = i + 1) begin\n                            if ((i < n) && (n >= 4'd1) && (n <= 4'd8) && (n[0] == 1'b1)) begin\n                                a[i] <= i[7:0];\n                                b[i] <= i[7:0];\n                                if ((2 * i) >= n) begin\n                                    c[i] <= (2 * i) - n[7:0];\n                                end else begin\n                                    c[i] <= 2 * i[7:0];\n                                end\n                            end else begin\n                                a[i] <= 8'd0;\n                                b[i] <= 8'd0;\n                                c[i] <= 8'd0;\n                            end\n                        end\n\n                        state <= DONE_ST;\n                        done <= 1'b1;\n                    end\n                end\n\n                DONE_ST: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule